interface Env { ASSETS?: { fetch(request: Request): Promise<Response> | Response }; ITEMS: DurableObjectNamespace<ItemStore>; CONNECTIONS?: unknown; ADMIN_WEB_KEY?: string; ADMIN_BOOTSTRAP_TOKEN_SHA256?: string; }
const V48_ASSET_PATH = "/DTF_Studio_V48.22E_VIEW_ALL_SYNCED.html";
function isGetOrHead(request: Request): boolean { const method = request.method.toUpperCase(); return method === "GET" || method === "HEAD"; }
let currentAdminTraceStage="ADMIN-TRACE-00";
function adminTrace(stage: string, request: Request, extra: Record<string, unknown> = {}): void { currentAdminTraceStage=stage; console.log(JSON.stringify({ stage, path: new URL(request.url).pathname, method: request.method, ...extra })); }
function safeError(error: unknown): {type:string;message?:string} { const type=error instanceof Error?error.constructor.name:"UnknownError"; const raw=error instanceof Error?error.message:"Unexpected runtime failure"; return /password|secret|token|cookie|hash|salt|key|verifier/i.test(raw)?{type}:{type,message:raw.slice(0,160)}; }
function adminDiagnostic(stage: string, error: unknown, request: Request): Response { const id=crypto.randomUUID().slice(0,8); const detail=safeError(error); console.error(JSON.stringify({diagnosticId:id,stage,path:new URL(request.url).pathname,method:request.method,...detail})); return new Response(`<!doctype html><html><body><main><h1>DTF STUDIO ADMIN DIAGNOSTIC</h1><p>Diagnostic ID: ${id}</p><p>Failed Stage: ${stage}</p><p>Exception Type: ${detail.type}</p>${detail.message?`<p>Exception Message: ${detail.message}</p>`:""}</main></body></html>`,{status:500,headers:{"content-type":"text/html; charset=utf-8","cache-control":"no-store"}}); }
function isStaticRequest(pathname: string): boolean { return pathname.startsWith("/assets/") || pathname.includes(".") || pathname === "/robots.txt"; }
async function assetFetch(request: Request, env: Env, pathname: string): Promise<Response> { if (!env.ASSETS) return new Response("Static assets are not configured.", { status: 503 }); const url = new URL(request.url); url.pathname = pathname; url.search = ""; url.hash = ""; const response = await env.ASSETS.fetch(new Request(url, request)); if (response.status === 404) return new Response("Not found", { status: 404 }); return new Response(response.body, { status: response.status, statusText: response.statusText, headers: response.headers }); }

async function printifyRequest(env: Env, path: string): Promise<unknown> { if (!env.CONNECTIONS) throw new Error("Printify connection is not available."); const connections = createConnections(env as any); const entry = await (env.CONNECTIONS as any).find("printify"); const response = await connections[entry.alias].fetch(path, { method: "GET" }); if (!response.ok) throw new Error(`Printify request failed (${response.status}).`); return JSON.parse(await response.text()); }
function normalizeBlueprint(row: any) { const id=String(row?.id??row?.blueprint_id??''); if(!/^\d{1,20}$/.test(id)) return null; return { blueprintId:id,title:String(row.title??row.name??'').slice(0,300),description:String(row.description??'').slice(0,5000),productType:String(row.model??row.type??row.product_type??'').slice(0,120),source:row,variants:Array.isArray(row.variants)?row.variants:[],images:Array.isArray(row.images)?row.images:[],sourceAvailable:true,syncStatus:'synced' }; }
function parseBlueprintCatalog(text: string): any[] { try { const parsed=JSON.parse(text); const root=Array.isArray(parsed)?parsed:(parsed?.data??parsed?.items??parsed?.blueprints??[]); return Array.isArray(root)?root:[]; } catch { const items:any[]=[]; let start=-1,depth=0,inString=false,escaped=false; for(let i=0;i<text.length;i++){const ch=text[i]; if(inString){if(escaped)escaped=false; else if(ch==='\\')escaped=true; else if(ch==='"')inString=false; continue;} if(ch==='"'){inString=true;continue;} if(ch==='{'){if(depth===0)start=i;depth++;} else if(ch==='}'&&depth>0){depth--;if(depth===0&&start>=0){try{const item=JSON.parse(text.slice(start,i+1));if(item&&item.id!=null)items.push(item);}catch{} start=-1;}}} return items; } }
function catalogSlug(value: unknown): string { return String(value ?? "").toLowerCase().normalize("NFKD").replace(/[\u0300-\u036f]/g, "").replace(/&/g, " and ").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "") || "other"; }
function buildCatalogCategories(products: any[]): any[] { const map=new Map<string,any>(); for(const p of products){ const name=String(p.categorySuggestion||"Other"), sub=String(p.subcategorySuggestion||"Other"), id=String(p.categoryId||catalogSlug(name)), subId=String(p.subcategoryId||catalogSlug(sub)); if(!map.has(id)) map.set(id,{id,name,count:0,subcategories:new Map<string,any>()}); const c=map.get(id); c.count++; if(!c.subcategories.has(subId)) c.subcategories.set(subId,{id:subId,name:sub,count:0}); c.subcategories.get(subId).count++; } return [...map.values()].map(c=>({id:c.id,name:c.name,count:c.count,subcategories:[...c.subcategories.values()].sort((a,b)=>a.name.localeCompare(b.name))})).sort((a,b)=>a.name.localeCompare(b.name)); }
async function loadPrintifySnapshot(request: Request, env: Env): Promise<any> {
  if (!env.ASSETS) throw new Error("Printify catalog snapshot assets are not configured.");
  const url = new URL("/data/printify-catalog.json", request.url);
  const response = await env.ASSETS.fetch(new Request(url, { method: "GET" }));
  if (!response.ok) throw new Error("Printify catalog snapshot is unavailable.");
  let snapshot: any; try { snapshot = await response.json(); } catch { throw new Error("Printify catalog snapshot is invalid JSON."); }
  if (snapshot?.schemaVersion !== 1 || snapshot?.source !== "printify-catalog-blueprints" || !Array.isArray(snapshot?.products) || snapshot.products.length === 0 || snapshot.total !== snapshot.products.length) throw new Error("Printify catalog snapshot failed validation.");
  for (const product of snapshot.products) { if (!/^(?:0|[1-9]\d*)$/.test(String(product?.blueprintId ?? "")) || !String(product?.title ?? "").trim()) throw new Error("Printify catalog snapshot contains an invalid product."); }
  return snapshot;
}
async function adminRbacApi(request: Request, env: Env): Promise<Response | null> {
  const url=new URL(request.url); if(!url.pathname.startsWith("/api/admin/rbac")) return null; const claims=await getAdminSessionClaims(request,env); const store=env.ITEMS.get(env.ITEMS.idFromName("default")); const identity=claims?await store.adminIdentity(claims.userId):null; if(!identity) return Response.json({ok:false,error:"Unauthorized"},{status:401}); const permission=request.method==="GET"?"access":"modify"; const resource=url.pathname.includes("/groups")?"admin.user_groups":"admin.users"; if(!await store.adminPermission(identity.id,resource,permission)) return Response.json({ok:false,error:"Permission denied."},{status:403});
  try { const method=request.method.toUpperCase(); if(method==="GET"&&url.pathname==="/api/admin/rbac/users") return Response.json({ok:true,users:await store.adminUsersDetailed()}); if(method==="GET"&&url.pathname==="/api/admin/rbac/groups") return Response.json({ok:true,groups:await store.adminGroups(),permissions:await store.adminPermissionMatrix("printing_technician")}); if(method==="GET"&&url.pathname==="/api/admin/rbac/audit") return Response.json({ok:true,audit:await store.adminAuditList()}); if(method==="POST"&&url.pathname==="/api/admin/rbac/users"){const body=await request.json() as any; const groupId=String(body.groupId||body.role||"group-printing-operator"); return Response.json({ok:true,user:await store.createAdminUserAsync(identity.id,String(body.username||""),String(body.password||""),groupId)});} if(method==="PATCH"&&/^\/api\/admin\/rbac\/users\/[^/]+\/group$/.test(url.pathname)){const id=url.pathname.split("/").slice(-2,-1)[0]||"";const body=await request.json() as any;return Response.json({ok:true,user:await store.setAdminUserGroup(identity.id,id,String(body.groupId||""))});} if(method==="PATCH"&&/^\/api\/admin\/rbac\/users\/[^/]+$/.test(url.pathname)){const id=url.pathname.split("/").pop()||"";const body=await request.json() as any;const result=body.role?store.setAdminUserRole(identity.id,id,body.role==="main_admin"?"main_admin":"printing_technician"):store.setAdminUserEnabled(identity.id,id,Boolean(body.enabled));return Response.json({ok:true,user:result});} return Response.json({ok:false,error:"Not found"},{status:404}); } catch(e){return Response.json({ok:false,error:e instanceof Error?e.message:"RBAC request failed"},{status:400});}
}

